use crate::error::Error;
use crate::{
    Author, Brand, BranefuckProgram, Cipher, Description, Edited, Music, Name, Sigil, Uploaded,
    error::{NumberError, StringError},
    sector::Compendium,
};
use crate::{BrandImage, prelude::*};
use base64::{Engine, prelude::BASE64_STANDARD};
use derive_more::Display;
use serde::{Deserialize, Serialize};
use std::{net::IpAddr, str::FromStr};
use time::OffsetDateTime;
use ulid::Ulid;

pub const MAX_COMMENT_LEN: usize = 256;
pub const MAX_PALETTE: u8 = 8;

const PACK_SECTION_COUNT: usize = 11;
const NODE_SECTION_COUNT: usize = 4;
const PACK_SECTION_SEPARATOR: char = '&';
const NODE_SECTION_SEPARATOR: char = '#';
const NODE_SEPARATOR: char = '$';
const EXIT_SEPARATOR: char = ',';

/// A Void Stranger pack
#[derive(Debug, Clone, Display, Serialize, Deserialize)]
#[display("{cipher}")]
pub struct Cluster {
    sigil: Sigil,
    cipher: Cipher,
    domain: Domain,
    origin: IpAddr,
}

/// Used to parse and validate the pack
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Domain {
    version: Version,
    name: Name,
    description: Description,
    author: Author,
    author_brand: Brand,
    author_brand_image: BrandImage,
    uploaded: Uploaded,
    edited: Edited,
    password: Password,
    thumbnail: Compendium,
    save_name: SaveName,
    nodes: Vec<Node>,
}

#[derive(Debug, Display, Clone, Serialize, Deserialize)]
pub struct Version(u8);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Password(Brand);

#[derive(Debug, Display, Clone, Copy, Serialize, Deserialize, Hash, Eq, PartialEq)]
pub struct SaveName(pub Ulid);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Node {
    /// Encoded as ro
    Root(RootNode),
    /// Encoded as br           
    Brand(BrandNode),
    /// Encoded as lv
    /// 
    /// Level nodes are boxed to reduce the size of the enum (from about 352 bytes to 72)
    /// Without that every instances of node would be of this size, whether it's level or not 
    Level(Box<LevelNode>),
    /// Encoded as re
    Redirect(RedirectNode),
    /// Encoded as mu
    Music(MusicNode),
    /// Encoded as bf
    Branefuck(BranefuckNode),
    /// Encoded as tn
    Thumbnail(ThumbnailNode),
    /// Encoded as ct
    Random(RandomNode),
    /// Encoded as cm
    Comment(CommentNode),
    /// Encoded as ob
    OutOfBounds(OutOfBoundsNode),
    /// Encoded as pl
    Palette(PaletteNode),
    /// Encoded as en
    End(EndNode),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BaseNode {
    position: Position,
    exits: Vec<Exit>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Position {
    x: i64,
    y: i64,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Exit(u64);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RootNode(BaseNode, Fall);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BrandNode(BaseNode, Brand);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RedirectNode(BaseNode);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LevelNode(BaseNode, Compendium);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct MusicNode(BaseNode, Music);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BranefuckNode(BaseNode, BranefuckProgram);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ThumbnailNode(BaseNode);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RandomNode(BaseNode);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CommentNode(BaseNode, Comment);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OutOfBoundsNode(BaseNode);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PaletteNode(BaseNode, Palette);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EndNode(BaseNode);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Fall(bool);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Comment(String);

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Palette(u8);

impl Cluster {
    pub fn inscribe(
        cipher: impl Into<String> + AsRef<str>,
        ip: IpAddr,
        latest_pack_version: impl Into<u8>,
        latest_level_version: impl Into<u8>,
        allowed_songs: impl AsRef<[String]>,
    ) -> Result<Self> {
        Ok(Self {
            sigil: Sigil::new(),
            domain: Domain::decipher(
                cipher.as_ref(),
                latest_pack_version,
                latest_level_version,
                allowed_songs,
            )?,
            cipher: Cipher(cipher.into()),
            origin: ip,
        })
    }

    pub fn amend(
        cipher: impl Into<String> + AsRef<str>,
        sigil: Sigil,
        ip: IpAddr,
        latest_pack_version: impl Into<u8>,
        latest_level_version: impl Into<u8>,
        allowed_songs: impl AsRef<[String]>,
    ) -> Result<Self> {
        Ok(Self {
            sigil,
            domain: Domain::decipher(
                cipher.as_ref(),
                latest_pack_version,
                latest_level_version,
                allowed_songs,
            )?,
            cipher: Cipher(cipher.into()),
            origin: ip,
        })
    }

    pub fn set_dates_to_now(&mut self) -> Result<()> {
        let sections: Vec<&str> = self
            .cipher
            .0
            .splitn(PACK_SECTION_COUNT, PACK_SECTION_SEPARATOR)
            .collect();

        if sections.len() != PACK_SECTION_COUNT {
            return Err(Error::InvalidStructure);
        }

        let version = sections[0];
        let name = sections[1];
        let description = sections[2];
        let author = sections[3];
        let author_brand = sections[4];

        // let uploaded = sections[5];
        // let edited = sections[6];

        let password = sections[7];
        let save_name = sections[8];
        let thumbnail = sections[9];
        let nodes = sections[10];

        let now = OffsetDateTime::now_utc()
            .date()
            .to_string()
            .replace('-', "");
        self.cipher = Cipher(format!(
            "{version}&{name}&{description}&{author}&{author_brand}&{now}&{now}&{password}&{save_name}&{thumbnail}&{nodes}"
        ));
        self.domain.uploaded = Uploaded(now.clone());
        self.domain.edited = Edited(now);
        Ok(())
    }

    pub fn set_uploaded_from(&mut self, cluster: &Self) -> Result<()> {
        let sections: Vec<&str> = self
            .cipher
            .0
            .splitn(PACK_SECTION_COUNT, PACK_SECTION_SEPARATOR)
            .collect();

        if sections.len() != PACK_SECTION_COUNT {
            return Err(Error::InvalidStructure);
        }

        let version = sections[0];
        let name = sections[1];
        let description = sections[2];
        let author = sections[3];
        let author_brand = sections[4];
        let uploaded = cluster.domain.uploaded.clone();
        let edited = sections[6];
        let password = sections[7];
        let save_name = sections[8];
        let thumbnail = sections[9];
        let nodes = sections[10];
        self.cipher = Cipher(format!(
            "{version}&{name}&{description}&{author}&{author_brand}&{uploaded}&{edited}&{password}&{save_name}&{thumbnail}&{nodes}"
        ));
        self.domain.uploaded = uploaded;
        Ok(())
    }

    #[must_use]
    pub fn version(&self) -> String {
        self.domain.version.to_string()
    }

    #[must_use]
    pub fn name(&self) -> String {
        self.domain.name.to_string()
    }

    #[must_use]
    pub fn author(&self) -> String {
        self.domain.author.to_string()
    }

    #[must_use]
    pub fn description(&self) -> String {
        self.domain.description.to_string()
    }

    #[must_use]
    pub fn brand(&self) -> String {
        self.domain.author_brand.to_string()
    }

    #[must_use]
    pub fn brand_image_base64(&self) -> String {
        self.domain.author_brand_image.base64.clone()
    }

    #[must_use]
    pub fn uploaded(&self) -> String {
        self.domain.uploaded.to_string()
    }

    #[must_use]
    pub fn edited(&self) -> String {
        self.domain.edited.to_string()
    }

    #[must_use]
    pub const fn save_name(&self) -> SaveName {
        self.domain.save_name
    }

    #[must_use]
    pub const fn sigil(&self) -> Sigil {
        self.sigil
    }

    #[must_use]
    pub fn sigil_string(&self) -> String {
        self.sigil.to_string()
    }

    #[must_use]
    pub fn nodeless_cipher(&self) -> String {
        self.cipher
            .0
            .match_indices(PACK_SECTION_SEPARATOR)
            .nth(PACK_SECTION_COUNT - 2)
            .map_or_else(
                || self.cipher.to_string(),
                |(index, _)| self.cipher.0.chars().take(index).collect()
            )
    }

    #[must_use]
    pub const fn number_of_nodes(&self) -> usize {
        self.domain.nodes.len()
    }

    #[must_use]
    pub fn number_of_levels(&self) -> usize {
        self.domain
            .nodes
            .iter()
            .filter_map(|node| match node {
                Node::Level(node) => Some(node),
                _ => None,
            })
            .count()
    }

    #[must_use]
    pub fn cipher(&self) -> String {
        self.cipher.to_string()
    }

    #[must_use]
    pub const fn origin(&self) -> IpAddr {
        self.origin
    }
}

impl Domain {
    fn decipher(
        cipher: impl AsRef<str>,
        latest_pack_version: impl Into<u8>,
        latest_level_version: impl Into<u8>,
        allowed_songs: impl AsRef<[String]>,
    ) -> Result<Self> {
        let sections: Vec<&str> = cipher
            .as_ref()
            .splitn(PACK_SECTION_COUNT, PACK_SECTION_SEPARATOR)
            .collect();

        if sections.len() != PACK_SECTION_COUNT {
            return Err(Error::InvalidStructure);
        }

        let latest_level_version = latest_level_version.into();
        let allowed_songs = allowed_songs.as_ref();

        let version = Version::from_str(sections[0], latest_pack_version)?;
        let name = sections[1].parse()?;
        let description = sections[2].parse()?;
        let author = Author::from_str(sections[3], false)?;
        let author_brand = sections[4].parse()?;
        let author_brand_image = BrandImage::new(&author_brand);
        let uploaded = Uploaded(sections[5].into());
        let edited = Edited(sections[6].into());
        let password = sections[7].parse()?;
        let save_name = sections[8].parse()?;
        let thumbnail =
            Compendium::decipher(sections[9], latest_level_version, allowed_songs, true)?;
        let nodes = sections[10]
            .split(NODE_SEPARATOR)
            .map(|s| Node::from_str(s, latest_level_version, allowed_songs))
            .collect::<Result<Vec<_>, _>>()?;

        Ok(Self {
            version,
            name,
            description,
            author,
            author_brand,
            author_brand_image,
            uploaded,
            edited,
            password,
            thumbnail,
            save_name,
            nodes,
        })
    }
}

impl Node {
    fn from_str(
        input: impl AsRef<str>,
        latest_level_version: impl Into<u8>,
        allowed_songs: impl AsRef<[String]>,
    ) -> Result<Self> {
        let sections: Vec<&str> = input
            .as_ref()
            .splitn(NODE_SECTION_COUNT, NODE_SECTION_SEPARATOR)
            .collect();

        if sections.len() != NODE_SECTION_COUNT {
            return Err(Error::InvalidStructure);
        }

        let node_id = sections[0];
        let position = sections[1];
        let exits = sections[2];
        let properties = sections[3];

        let base_node = BaseNode {
            exits: if exits.is_empty() {
                vec![]
            } else {
                exits
                    .split(EXIT_SEPARATOR)
                    .map(str::parse)
                    .collect::<Result<_, _>>()?
            },
            position: position.parse()?,
        };

        match node_id {
            "ro" => Ok(Self::Root(RootNode(base_node, properties.parse()?))),
            "br" => Ok(Self::Brand(BrandNode(base_node, properties.parse()?))),
            "lv" => Ok(Self::Level(Box::new(LevelNode(
                base_node,
                Compendium::decipher(properties, latest_level_version, allowed_songs, true)?,
            )))),
            "re" => Ok(Self::Redirect(RedirectNode(base_node))),
            "mu" => Ok(Self::Music(MusicNode(
                base_node,
                Music::from_str(properties, allowed_songs)?,
            ))),
            "bf" => Ok(Self::Branefuck(BranefuckNode(
                base_node,
                properties.parse()?,
            ))),
            "tn" => Ok(Self::Thumbnail(ThumbnailNode(base_node))),
            "ct" => Ok(Self::Random(RandomNode(base_node))),
            "cm" => Ok(Self::Comment(CommentNode(base_node, properties.parse()?))),
            "ob" => Ok(Self::OutOfBounds(OutOfBoundsNode(base_node))),
            "pl" => Ok(Self::Palette(PaletteNode(base_node, properties.parse()?))),
            "en" => Ok(Self::End(EndNode(base_node))),
            other => Err(Error::InvalidNode(other.into())),
        }
    }
}

impl Version {
    /// Parses input as an integer for a pack's format version
    ///
    /// # Errors
    ///
    /// Returns an error if the input wasn't a number, was too
    /// big, or was too small.
    pub fn from_str(input: &str, latest_version: impl Into<u8>) -> Result<Self> {
        let latest_version = latest_version.into();
        let version = input
            .parse::<u8>()
            .map_err(|why| Error::InvalidVersion(NumberError::NotANumber(why)))?;
        let too_big = version > latest_version;
        let too_small = version < latest_version;

        if too_big {
            return Err(Error::InvalidVersion(NumberError::TooBig {
                max: u64::from(latest_version),
                found: u64::from(version),
            }));
        }
        if too_small {
            return Err(Error::InvalidVersion(NumberError::TooSmall {
                min: i64::from(latest_version),
                found: i64::from(version),
            }));
        }
        Ok(Self(version))
    }
}

impl FromStr for Exit {
    type Err = Error;

    fn from_str(s: &str) -> Result<Self> {
        let exit = s
            .parse::<u64>()
            .map_err(|why| Error::InvalidExit(NumberError::NotANumber(why)))?;

        Ok(Self(exit))
    }
}

impl FromStr for Position {
    type Err = Error;

    fn from_str(s: &str) -> Result<Self> {
        let (x, y) = s.split_once(',').ok_or(Error::InvalidPosition)?;

        Ok(Self {
            x: x.parse()
                .map_err(|why| Error::InvalidPositionCoordinate(NumberError::NotANumber(why)))?,
            y: y.parse()
                .map_err(|why| Error::InvalidPositionCoordinate(NumberError::NotANumber(why)))?,
        })
    }
}

impl FromStr for Fall {
    type Err = Error;

    fn from_str(s: &str) -> Result<Self> {
        match s {
            "0" => Ok(Self(false)),
            "1" => Ok(Self(true)),
            other => Err(Error::InvalidFall(other.into())),
        }
    }
}

impl FromStr for Comment {
    type Err = Error;

    fn from_str(s: &str) -> Result<Self> {
        let comment = String::from_utf8(
            BASE64_STANDARD
                .decode(s)
                .map_err(|why| Error::InvalidComment(StringError::Base64(why)))?,
        )
        .map_err(|why| Error::InvalidComment(StringError::FromUtf8(why)))?;
        if comment.len() > MAX_COMMENT_LEN {
            return Err(Error::InvalidComment(StringError::TooLong {
                max: MAX_COMMENT_LEN as u64,
                found: comment.len() as u64,
            }));
        }
        Ok(Self(comment))
    }
}

impl FromStr for Palette {
    type Err = Error;

    fn from_str(s: &str) -> Result<Self> {
        let palette = s
            .parse::<u8>()
            .map_err(|why| Error::InvalidPalette(NumberError::NotANumber(why)))?;

        let too_big = palette > MAX_PALETTE;

        if too_big {
            return Err(Error::InvalidPalette(NumberError::TooBig {
                max: u64::from(MAX_PALETTE),
                found: u64::from(palette),
            }));
        }

        Ok(Self(palette))
    }
}

impl FromStr for SaveName {
    type Err = Error;

    fn from_str(input: &str) -> Result<Self> {
        Ok(Self(input.parse()?))
    }
}

impl FromStr for Password {
    type Err = Error;

    fn from_str(input: &str) -> Result<Self> {
        let brand = String::from_utf8(
            BASE64_STANDARD
                .decode(input)
                .map_err(|why| Error::InvalidPassword(StringError::Base64(why)))?,
        )
        .map_err(|why| Error::InvalidPassword(StringError::FromUtf8(why)))?;

        Ok(Self(brand.parse()?))
    }
}

